async reserve(sku: string, quantity: number): Promise<void> {
  const rows = (await this.dataSource.manager.query('SELECT reserved FROM stock WHERE sku = $1', [sku])) as { reserved: number }[];
  const next = rows[0].reserved + quantity;
  await this.dataSource.manager.query('UPDATE stock SET reserved = $2 WHERE sku = $1', [sku, next]);
}
